    chosen.forEach(([h,v],i)=>{const cx=13+slot*i+slot/2,hh=Math.max(2,Math.abs(v.pnl)/max*48),positive=v.pnl>=0,yy=positive?base-hh:base;bars+=`<rect x="${cx-bw/2}" y="${yy}" width="${bw}" height="${hh}" rx="4" fill="${positive?'#10b981':'#ef4444'}" opacity=".9"/><text x="${cx}" y="${H-9}" text-anchor="middle" font-size="8" fill="#718096">${h}</text>`});
