    $('saveSettings').onclick=async()=>{app.data.settings={...app.data.settings,gasUrl:$('gasUrl').value.trim(),apiToken:$('apiToken').value.trim(),autoSync:$('autoSync').checked,sheetName:$('sheetName').value.trim()||'Journal'};await persist();populateSettings();toast('تنظیمات ذخیره شد.')};
    $('registerPasskey').onclick=async()=>{try{await registerPasskey()}catch(err){toast(err.message||'فعال‌سازی Passkey ناموفق بود.')}};
    $('removePasskey').onclick=removePasskey;
    $('sideBuyBtn').onclick=()=>{ $('fSide').value='Buy'; $('sideBuyBtn').classList.add('active'); $('sideSellBtn').classList.remove('active'); $('sideBuyBtn').setAttribute('aria-pressed','true'); $('sideSellBtn').setAttribute('aria-pressed','false')};$('sideSellBtn').onclick=()=>{ $('fSide').value='Sell'; $('sideSellBtn').classList.add('active'); $('sideBuyBtn').classList.remove('active'); $('sideSellBtn').setAttribute('aria-pressed','true'); $('sideBuyBtn').setAttribute('aria-pressed','false')};$('tradeForm').addEventListener('submit',addManualTrade);$('tradeSearch').addEventListener('input',renderTrades);$('tradeSort').addEventListener('change',renderTrades);$('tradeFilters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;app.currentFilter=b.dataset.filter;$('tradeFilters').querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===b));renderTrades()});
