  function initActivityTracking(){['pointerdown','keydown','touchstart','click'].forEach(evt=>document.addEventListener(evt,()=>touchSession(),{passive:true}));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&app.key){if(sessionExpired())lockForInactivity();else touchSession(true)}})}
  async function init(){bindEvents();initActivityTracking();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});if(localStorage.getItem(AUTH_KEY)){const resumed=await resumeRememberedSession();if(resumed)await showApp({remember:false});else showLogin(false)}else showLogin(true)}
  init().catch(err=>{console.error(err);showLogin(Boolean(!localStorage.getItem(AUTH_KEY))) });
